    def test_source_repository_merge_base_and_metadata_are_checked(self):
        original = copy.deepcopy(self.api.source)
        mutations = [lambda x: x.update(merged=False),
                     lambda x: x.update(number=8),
                     lambda x: x["base"].update(ref="other"),
                     lambda x: x["base"]["repo"].update(id=1),
                     lambda x: x.update(merge_commit_sha="bad"),
                     lambda x: x.update(changed_files=2)]
        for change in mutations:
            with self.subTest(change=change), self.assertRaises(c.Failure):
                self.api.source = copy.deepcopy(original)
                change(self.api.source)
                self.executor.validate()

