    def test_paths_reject_traversal_controls_backslashes_and_non_al(self):
        for path in ("src/../x.al", "/src/a.al", "src//a.al", "src/./a.al",
                     "src\\a.al", "src/a\nb.al", "src/a\x00.al", "src/a\x7f.al",
                     ".github/x.al", "src/a.py", "src/C:/a.al", "src/CON.al",
                     "src/a. /b.al", "src/.git/a.al"):
            with self.subTest(path=path), self.assertRaises(c.Failure):
                c.validate_path(path)
        self.assertEqual(c.validate_path("src/Module/My Code.al"), "src/Module/My Code.al")

    def test_raw_entries_reject_executable_symlink_gitlink_and_control_paths(self):
        oid = b"a" * 40
        for mode in (b"100755", b"120000", b"160000"):
            raw = b":100644 " + mode + b" " + oid + b" " + oid + b" M\0src/a.al\0"
            with self.subTest(mode=mode), self.assertRaises(c.Failure):
                c.parse_raw_diff(raw)
        with self.assertRaises(c.Failure):
            c.parse_raw_diff(b":100644 100644 " + oid + b" " + oid + b" M\0src/a\nb.al\0")

    def test_size_limits_and_binary_blobs_are_rejected(self):
        for contents in (b"a\0b", b"x" * (1024 * 1024 + 1)):
            with self.subTest(size=len(contents)):
                git(self.origin, "switch", "feature")
                (self.origin / "src/one.al").write_bytes(contents)
                git(self.origin, "commit", "-am", "large or binary")
                head = git(self.origin, "rev-parse", "HEAD")
                git(self.origin, "update-ref", "refs/pull/7/head", head)
                git(self.origin, "switch", "main")
                git(self.origin, "reset", "--hard", self.target)
                git(self.origin, "merge", "--squash", "feature")
                git(self.origin, "commit", "-m", "squash")
                self.api.source.update(merge_commit_sha=git(self.origin, "rev-parse", "HEAD"))
                self.api.source["head"]["sha"] = head
                self.api.commits = [{"sha": value} for value in git(
                    self.origin, "rev-list", "--reverse", self.target + ".." + head).splitlines()]
                with self.assertRaises(c.Failure):
                    self.executor.validate()

