    def test_clean_cherry_pick_publish_and_duplicate_reconcile(self):
        result = self.stages()
        self.assertEqual(result["status"], "applied")
        self.assertFalse(result["published"])
        patch_bytes = (self.config.state_dir / "patch.bin").read_bytes()
        self.assertEqual(result["patch_sha256"], hashlib.sha256(patch_bytes).hexdigest())
        published = self.executor.publish()
        self.assertEqual(published["status"], "pr-created")
        self.assertEqual(published["pr_url"], self.api.pulls[0]["html_url"])
        self.assertEqual(self.executor.publish()["status"], "pr-reused")
        self.assertEqual(self.executor.track()["issue_number"], 101)
        self.assertEqual(len(self.api.issues), 1)
        self.assertEqual(len(self.api.pulls), 1)
        self.assertEqual([len(x) for x in self.api.comments.values()], [1, 1])
        branch = "refs/heads/backport/29.x/pr-7"
        self.assertEqual(git(self.origin, "show", branch + ":src/one.al").splitlines(), ["ONE", "two", "three"])
        self.assertEqual(git(self.origin, "rev-parse", branch + "^"), self.target)

    def test_full_rerun_after_publication_reuses_issue_and_pr(self):
        self.assertEqual(self.stages("publish")["status"], "pr-created")
        listed = self.executor.pages("/issues?state=all")
        self.assertEqual(len(listed), 2)
        self.assertEqual(sum("pull_request" in obj for obj in listed), 1)
        self.assertTrue(all(self.executor.marker(self.executor.read_plan()) in obj["body"] for obj in listed))
        head = git(self.origin, "rev-parse", "backport/29.x/pr-7")
        creates = sum(method == "POST" for method, _, _ in self.api.calls)
        for attempt in ("1", "2"):
            with self.subTest(attempt=attempt):
                self.env["GITHUB_RUN_ATTEMPT"] = attempt
                if attempt == "2":
                    # New jobs use fresh attempt-bound artifacts, not the old journal.
                    self.env["STATE_DIR"] = str(self.root / "attempt-2-state")
                self.configure()
                self.assertEqual(self.stages("publish")["status"], "pr-reused")
                self.assertEqual(self.executor.read_plan()["run_attempt"], attempt)
                self.assertEqual(len(self.api.issues), 1)
                self.assertEqual(len(self.api.pulls), 1)
                self.assertEqual(sum(method == "POST" for method, _, _ in self.api.calls), creates)
                self.assertEqual(git(self.origin, "rev-parse", "backport/29.x/pr-7"), head)
