    def test_push_lease_rejects_racing_fast_forward_target_without_changes(self):
        self.stages()
        branch = self.executor.branch
        original = c.GitRepo.push
        def racing_push(repo, name):
            self.assertEqual(name, branch)
            self.assertIsNone(repo.branch_head(name))
            # A plain push would fast-forward this competing branch to HEAD.
            git(self.origin, "branch", name, self.target)
            self.assertTrue(repo.ancestor(self.target, "HEAD"))
            with patch.object(repo, "command", wraps=repo.command) as command:
                try:
                    original(repo, name)
                finally:
                    args, kwargs = command.call_args
                    self.assertIn("--force-with-lease=refs/heads/" + name + ":", args[0])
                    self.assertTrue(kwargs["auth"])
        before = git(self.origin, "show-ref")
        with patch.object(c.GitRepo, "push", new=racing_push):
            with self.assertRaisesRegex(c.Failure, "^push_failed_or_ambiguous$"):
                self.executor.publish()
        self.assertEqual(git(self.origin, "rev-parse", branch), self.target)
        after = git(self.origin, "show-ref").splitlines()
        self.assertEqual(sorted(after), sorted(before.splitlines() + [self.target + " refs/heads/" + branch]))
        self.assertFalse(self.api.pulls)
        self.assertFalse(self.api.comments)

